<script setup lang="ts">
import { onMounted, ref } from 'vue'
import Sidebar from './Sidebar.vue'
import { useChatStore } from './store'
const store = useChatStore(), knowledge = ref<any>(null), configuration = ref<any>(null), selections = ref<Record<string, string | null>>({}), message = ref(''), busy = ref(false)
const labels: Record<string, string> = { retrieval: '召回、融合与重排', answer: '改写与上下文', agent: '执行策略', review: '检查与纠错', loop: '复杂任务循环（显式启用）' }
async function api(url: string, method = 'GET', body?: unknown) { const r = await fetch(url, { method, headers: { 'Content-Type': 'application/json', ...store.headers() }, ...(body ? { body: JSON.stringify(body) } : {}) }); if (!r.ok) throw new Error(`操作未完成 ${r.status}：${await r.text()}`); return r.json() }
async function load() { try { knowledge.value = await api('/api/knowledge'); configuration.value = await api('/api/configuration'); selections.value = { ...configuration.value.selections } } catch (e) { message.value = String(e) } }
async function action(url: string, method = 'POST', body?: unknown) { busy.value = true; try { const result = await api(url, method, body); message.value = JSON.stringify(result); await load() } catch (e) { message.value = String(e) } finally { busy.value = false } }
onMounted(load)
</script>
<template><div class="workspace"><Sidebar/><main class="management-main"><header><div><h1>知识与配置</h1><p>追加索引、显式发布；请求保留自己的版本快照。</p></div></header><section class="management-content"><label>本地访问令牌 <input v-model="store.token" type="password" autocomplete="off"></label> <button :disabled="busy" @click="load">刷新</button><p aria-live="polite">{{ message }}</p><section class="management-card"><h2>知识与索引</h2><p>导入已确认示例知识，构建新索引；真实模式调用 Embedding。当前不支持任意上传与自动审核新规则。</p><button :disabled="busy" @click="action('/api/knowledge/import')">导入示例知识（不切换发布）</button><table><thead><tr><th>知识版本 / 索引</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="i in knowledge?.indexes || []" :key="i.id"><td>{{ i.knowledge_version }}<small>{{ i.id }}</small></td><td>{{ i.status }} {{ i.selected ? '· 当前选择' : '' }}</td><td><button :disabled="busy || i.status !== 'published' || i.selected" @click="action(`/api/indexes/${i.id}/select`)">选择索引</button><button :disabled="busy || i.status !== 'published'" @click="action(`/api/indexes/${i.id}/bm25`)">构建 BM25</button></td></tr></tbody></table><details><summary>文档来源、版本与入库任务</summary><pre>{{ JSON.stringify({ documents: knowledge?.documents, jobs: knowledge?.jobs }, null, 2) }}</pre></details></section><section v-if="configuration" class="management-card"><h2>版本化预设</h2><p>应用后影响新请求；澄清、恢复和正在运行的任务沿用原配置。BM25/双路先构建派生产物；纠错与执行策略需兼容。选择 loop-v1-repair 必须同时选择 loop-post-required 审核；旧 slice1 预设仅保留历史身份，当前代码不再接受；off、pre-only、前置检查和旧纠错预设不兼容。循环仅接管 dynamic，其他路由保留原行为。</p><label v-for="(items, kind) in configuration.presets" :key="kind" class="preset-field">{{ labels[String(kind)] }} <select v-model="selections[String(kind)]"><option :value="null">基础默认</option><option v-for="item in items as any[]" :key="item.key" :value="item.key">{{ item.configuration.id }} · v{{ item.configuration.version }}</option></select></label><button :disabled="busy" @click="action('/api/configuration', 'PUT', { revision: configuration.revision, ...selections })">应用到后续请求</button><p>修订 {{ configuration.revision }} · 指纹 {{ configuration.fingerprint }}</p><details><summary>有效配置与依赖</summary><pre>{{ JSON.stringify(configuration.effective, null, 2) }}</pre></details><details><summary>预设内容</summary><pre>{{ JSON.stringify(configuration.presets, null, 2) }}</pre></details></section></section></main></div></template>
